-- Platform Cost & Attribution 1.1.0 — consumer and agent grants
--
-- Every object is granted by name. GRANT ... ON ALL VIEWS would widen
-- the product silently the next time a view is added to the schema.
--
-- Consumers: ROLE_FINANCE_ANALYST, ROLE_ENG_LEAD
--
-- Generated by the Observability & FinOps Platform. Review before running.
-- The platform does not execute this script; a human does (R2, R8).

USE ROLE SECURITYADMIN;

GRANT USAGE ON DATABASE OBSERVABILITY TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.PUBLISHED TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.SEMANTIC TO ROLE SNOWOBS_CONSUMER;

GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_FINOPS_CHARGEBACK_QUERY_EXECUTION TO ROLE SNOWOBS_CONSUMER;
GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_FINOPS_CHARGEBACK_COST_DAILY TO ROLE SNOWOBS_CONSUMER;
GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_FINOPS_CHARGEBACK_WAREHOUSE_METERING_HOURLY TO ROLE SNOWOBS_CONSUMER;

GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.FINOPS_CHARGEBACK TO ROLE SNOWOBS_CONSUMER;
GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.FINOPS_CHARGEBACK TO ROLE SNOWOBS_AGENT_USER;

GRANT USAGE ON AGENT OBSERVABILITY.AGENT.FINOPS_CHARGEBACK_AGENT TO ROLE SNOWOBS_AGENT_USER;
GRANT USAGE ON WAREHOUSE WH_SNOWOBS_AGENT TO ROLE SNOWOBS_AGENT_USER;

-- Grant the consumer role onward to the registered consumers. Each line is
-- one entry in the product's consumer register; adding a consumer is a
-- registry change, not an ad-hoc grant.
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_FINANCE_ANALYST;  -- Finance business partnering
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_ENG_LEAD;  -- Engineering leadership

SHOW GRANTS TO ROLE SNOWOBS_CONSUMER;
